mkitem!{mkstruct!{# [doc = " An error which can be returned when parsing an integer."] # [doc = ""] # [doc = " For example, this error is returned by the `from_str_radix()` functions"] # [doc = " on the primitive integer types (such as [`i8::from_str_radix`])"] # [doc = " and is used as the error type in their [`FromStr`] implementations."] # [doc = ""] # [doc = " [`FromStr`]: crate::str::FromStr"] # [doc = ""] # [doc = " # Potential causes"] # [doc = ""] # [doc = " Among other causes, `ParseIntError` can be thrown because of leading or trailing whitespace"] # [doc = " in the string e.g., when it is obtained from the standard input."] # [doc = " Using the [`str::trim()`] method ensures that no whitespace remains before parsing."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " if let Err(e) = i32::from_str_radix(\"a12\", 10) {"] # [doc = "     println!(\"Failed conversion to i32: {e}\");"] # [doc = " }"] # [doc = " ```"] # [derive (Debug , Clone , PartialEq , Eq)] # [stable (feature = "rust1" , since = "1.0.0")] pub struct ParseIntError { pub (super) kind : IntErrorKind , }}}
mkitem!{mkenum!{# [doc = " Enum to store the various types of errors that can cause parsing an integer to fail."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " # fn main() {"] # [doc = " if let Err(e) = i32::from_str_radix(\"a12\", 10) {"] # [doc = "     println!(\"Failed conversion to i32: {:?}\", e.kind());"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [stable (feature = "int_error_matching" , since = "1.55.0")] # [derive (Debug , Clone , PartialEq , Eq , Copy , Hash)] # [non_exhaustive] pub enum IntErrorKind { # [doc = " Value being parsed is empty."] # [doc = ""] # [doc = " This variant will be constructed when parsing an empty string."] # [stable (feature = "int_error_matching" , since = "1.55.0")] Empty , # [doc = " Contains an invalid digit in its context."] # [doc = ""] # [doc = " Among other causes, this variant will be constructed when parsing a string that"] # [doc = " contains a non-ASCII char."] # [doc = ""] # [doc = " This variant is also constructed when a `+` or `-` is misplaced within a string"] # [doc = " either on its own or in the middle of a number."] # [stable (feature = "int_error_matching" , since = "1.55.0")] InvalidDigit , # [doc = " Integer is too large to store in target integer type."] # [stable (feature = "int_error_matching" , since = "1.55.0")] PosOverflow , # [doc = " Integer is too small to store in target integer type."] # [stable (feature = "int_error_matching" , since = "1.55.0")] NegOverflow , # [doc = " Value was Zero"] # [doc = ""] # [doc = " This variant will be emitted when the parsing string has a value of zero, which"] # [doc = " would be illegal for non-zero types."] # [stable (feature = "int_error_matching" , since = "1.55.0")] Zero , }}}
mkitem!{mkimpl!{impl ParseIntError { # [doc = " Outputs the detailed cause of parsing an integer failing."] # [must_use] # [rustc_const_stable (feature = "const_int_from_str" , since = "1.82.0")] # [stable (feature = "int_error_matching" , since = "1.55.0")] pub const fn kind (& self) -> & IntErrorKind { & self . kind } }}}
mkitem!{mkimpl!{# [stable (feature = "rust1" , since = "1.0.0")] impl fmt :: Display for ParseIntError { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { match self . kind { IntErrorKind :: Empty => "cannot parse integer from empty string" , IntErrorKind :: InvalidDigit => "invalid digit found in string" , IntErrorKind :: PosOverflow => "number too large to fit in target type" , IntErrorKind :: NegOverflow => "number too small to fit in target type" , IntErrorKind :: Zero => "number would be zero for non-zero type" , } . fmt (f) } }}}
